    "detail": {
      "aboutTemplate": "Let’s learn to spell {name} — listen to each letter!",
      "funFactTemplate": "Every letter in {name} has its own sound!",
      "tryTemplate": "Spell {name} slowly in the air, one letter at a time!"
    },
