      "mama": "Mother's brother",
      "mami": "Mother's brother's wife",
      "masi": "Mother's sister",
      "masa": "Mother's sister's husband",
      "motaPapa": "Father's elder brother",
      "motaMummy": "Father's elder brother's wife",
      "chacha": "Father's younger brother",
      "chachi": "Father's younger brother's wife",
      "bua": "Father's sister",
      "fufa": "Father's sister's husband",
