    "detail": {
      "aboutTemplate": "Let's explore {name}!",
      "funFactTemplate": "Math helps us every day!",
      "tryTemplate": "Say {name} out loud with a grown-up!",
      "moreLess": {
        "about": "More means a bigger group. Less means a smaller group. Count each group to compare them!",
        "funFact": "When you share snacks, you can see who has more pieces and who has less.",
        "try": "Put 3 blocks in one pile and 5 in another. Which pile has more?"
      },
      "bigSmall": {
        "about": "Big things take more space. Small things take less space. We compare sizes every day!",
        "funFact": "An elephant is big. A mouse is small. Can you name something big and something small near you?",
        "try": "Find one big object and one small object in your room."
      },
      "patterns": {
        "about": "A pattern repeats again and again — like red, blue, red, blue. Can you guess what comes next?",
        "funFact": "Stripes on a shirt, tiles on a floor, and beads on a necklace often make patterns!",
        "try": "Clap a pattern: clap-clap-pause, clap-clap-pause. Repeat it three times!"
      },
      "sorting": {
        "about": "Sorting means putting things in groups — by color, size, or shape. It helps us stay organized!",
        "funFact": "You might sort toys, clothes, or fruits into groups without even thinking about it.",
        "try": "Sort 6 buttons or coins into two color groups with a grown-up."
      },
      "counting": {
        "about": "Counting means saying numbers one by one while pointing at each object. One touch for each item!",
        "funFact": "You can count steps, fingers, fruits, or birds — counting is everywhere!",
        "try": "Count aloud from 1 to 10 while touching each finger."
      },
